import json
Q=[]
def q(n,ru,kk,ropts,kopts=None,**kw):
    d={'n':n,'ru':{'q':ru,'opts':ropts},'kk':{'q':kk,'opts':kopts if kopts is not None else ropts}}; d.update(kw); Q.append(d)
q(1,"Из поселка и города навстречу друг другу одновременно выехали два автобуса. Один автобус до встречи проехал 595 км со скоростью 85 км/ч. Сколько километров до встречи проехал второй автобус, если его скорость 35 км/ч?","Кент пен қаладан бір-біріне қарсы екі автобус бір мезгілде шықты. Бір автобус кездескенге дейін 85 км/сағ жылдамдықпен 595 км жүрді. Екінші автобустың жылдамдығы 35 км/сағ болса, ол кездескенге дейін неше километр жүрді?",["235","245","255","840"])
q(2,"В первый день Алуа прочитала 55 страниц, что составляет 11/26 всех страниц книги. Сколько всего страниц в книге?","Алуа бірінші күні 55 бет оқыды, бұл кітаптың барлық беттерінің 11/26 бөлігін құрайды. Кітапта барлығы неше бет бар?",["260","130","104","156"])
q(3,"Весь путь поделен на равные части. В первый день путешественники преодолели две части пути, во второй три, а в третий день еще две части пути. Какое расстояние преодолели путешественники в первый день, если весь путь составлял 413 км?","Бүкіл жол тең бөліктерге бөлінген. Бірінші күні саяхатшылар жолдың екі бөлігін, екінші күні үшеуін, ал үшінші күні тағы екі бөлігін жүріп өтті. Бүкіл жол 413 км болса, бірінші күні саяхатшылар қанша қашықтық жүрді?",["59","118","177","236"])
q(4,"В банк привезли 2 миллиона тенге однотенговыми купюрами. Сколько понадобится рабочих дней, чтобы пересчитать купюры, если: 1) Рабочий день 8 часов. 2) Скорость счета 1 купюра в секунду. Счет в рабочий день идет непрерывно.","Банкке 2 миллион теңге бір теңгелік купюрамен әкелінді. Купюраларды қайта санау үшін неше жұмыс күні қажет, егер: 1) Жұмыс күні 8 сағат. 2) Санау жылдамдығы секундына 1 купюра. Жұмыс күні ішінде санау үздіксіз жүреді.",["68","69","70","71"])
q(5,"На участке дороги бетонные плиты длиной 7 м заменили новыми длиной 9 м. Сколько нужно новых плит для замены 99 старых?","Жол учаскесінде ұзындығы 7 м бетон плиталарды ұзындығы 9 м жаңаларымен ауыстырды. 99 ескі плитаны ауыстыру үшін неше жаңа плита қажет?",["66","77","88","70"])
q(6,"Из лука сделано 40 выстрелов. 30 стрел пролетело мимо мишени. Определите процент попадания.","Садақтан 40 рет оқ атылды. 30 жебе нысанадан өтіп кетті. Тию пайызын анықтаңыз.",["25%",r"\(\tfrac14\%\)","50%","75%"])
q(7,"Найдите половину суммы (НОД) и (НОК) двух данных чисел 40 и 72.","Берілген екі санның 40 және 72 (ЕҮОБ) мен (ЕКОЕ) қосындысының жартысын табыңыз.",["156","368","182","184"])
q(8,"За 7 месяцев работы завод выполнил 84% объема годового плана. На сколько % завод перевыполнит годовой план, если будет работать в таком же темпе?","Зауыт 7 ай жұмыс істегенде жылдық жоспар көлемінің 84%-ын орындады. Осындай қарқынмен жұмыс істесе, зауыт жылдық жоспарды неше пайызға артығымен орындайды?",["144%","24%","44%","42%"])
q(9,"Из хлопка-сырца получается 30% волокна. Сколько надо взять хлопка-сырца, чтобы получить 120 кг волокна?","Шикі мақтадан 30% талшық алынады. 120 кг талшық алу үшін қанша шикі мақта алу керек?",["36","400","360","420"])
q(10,r"На окраску окон и дверей было потрачено 2,4 кг белил, что составляет \(\tfrac47\) всех белил, потраченных на ремонт. А на ремонт было потрачено \(\tfrac16\) всех купленных белил. Сколько кг белил было куплено?",r"Терезелер мен есіктерді бояуға 2,4 кг ақ бояу жұмсалды, бұл жөндеуге жұмсалған барлық ақ бояудың \(\tfrac47\) бөлігін құрайды. Ал жөндеуге сатып алынған барлық ақ бояудың \(\tfrac16\) бөлігі жұмсалды. Барлығы неше кг ақ бояу сатып алынды?",["4,2","18,6","22,6","25,2"])
q(11,"Четверо мальчиков бросали баскетбольный мяч в корзину. У Алмаса из 7 бросков было 5 попаданий, а у Богдана из 8 бросков было 6 попаданий, у Магжана из 9 бросков было 7 попаданий, у Еркебулана из 6 бросков было 4 попадания. Чей результат лучше?","Төрт бала баскетбол добын себетке лақтырды. Алмаста 7 лақтырыстан 5 тию, Бөгдан 8 лақтырыстан 6 тию, Мағжанда 9 лақтырыстан 7 тию, Еркебұланда 6 лақтырыстан 4 тию болды. Кімнің нәтижесі жақсырақ?",["Алмас","Богдан","Магжан","Еркебулан"],["Алмас","Бөгдан","Мағжан","Еркебұлан"])
q(12,"Скорость велосипедиста во столько же раз выше скорости пешехода, во сколько раз скорость велосипедиста меньше скорости мотоциклиста. Найти отношение скорости велосипедиста к скорости мотоциклиста, если известно, что скорость пешехода в 25 раз меньше скорости мотоциклиста.","Велосипедшінің жылдамдығы жаяу жүргіншінің жылдамдығынан неше есе артық болса, велосипедшінің жылдамдығы мотоциклшінің жылдамдығынан сонша есе аз. Жаяу жүргіншінің жылдамдығы мотоциклшінің жылдамдығынан 25 есе аз екені белгілі болса, велосипедші жылдамдығының мотоциклші жылдамдығына қатынасын табыңыз.",["1 : 5","5 : 1","1 : 25","25 : 1"])
q(13,"Отрезок длиной 2256 см разделили на три отрезка в отношении 0,8 : 1,2 : 2. Найдите длину меньшего отрезка.","Ұзындығы 2256 см кесіндіні 0,8 : 1,2 : 2 қатынасындай үш кесіндіге бөлді. Кіші кесіндінің ұзындығын табыңыз.",["451,2","676,8","1128","225,6"])
